from collections import Counter, deque

def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    bg=Counter(v for row in a for v in row).most_common(1)[0][0]
    seen=set()
    for r in range(h):
      for c in range(w):
        if a[r][c]==bg or (r,c) in seen: continue
        val=a[r][c]; q=deque([(r,c)]); seen.add((r,c)); comp=[]
        while q:
          rr,cc=q.popleft(); comp.append((rr,cc))
          for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
            if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and a[nr][nc]==val:
              seen.add((nr,nc)); q.append((nr,nc))
        r0=min(rr for rr,cc in comp); r1=max(rr for rr,cc in comp)
        c0=min(cc for rr,cc in comp); c1=max(cc for rr,cc in comp)
        rh=r1-r0+1; cw=c1-c0+1
        cells=set(comp)
        if rh<3 or cw<3: continue
        # verify this component is precisely a 1-cell rectangular frame, with a uniform empty interior
        perimeter={(rr,cc) for rr in range(r0,r1+1) for cc in range(c0,c1+1) if rr in (r0,r1) or cc in (c0,c1)}
        inside={(rr,cc) for rr in range(r0+1,r1) for cc in range(c0+1,c1)}
        if cells==perimeter and all(a[rr][cc]==bg for rr,cc in inside):
          fill=2 if rh%2==0 and cw%2==0 else 7
          for rr,cc in inside: a[rr][cc]=fill
    return a

